/**
 * Command routing logic for CLI
 *
 * @module cli/router
 */
import * as dntShim from "../_dnt.shims.js";
import { isIntegrationErrorContext, readIntegrationErrorContext, readIntegrationThrowableContext, } from "../src/integrations/error-context.js";
import { cliErrorBoundary } from "../src/errors/index.js";
import { cliLogger, isVerbose, VERSION } from "./utils/index.js";
import { getStructuredCommandHelp, getStructuredMainHelp, showCommandHelp, showMainHelp, } from "./help/index.js";
import { setColorOverride, shouldUseColor } from "./ui/colors.js";
import { exitProcess, setQuietMode, setVerboseMode } from "./utils/index.js";
import { ensureCliSchemaValidator } from "./shared/default-contracts.js";
import { createErrorEnvelope, createSuccessEnvelope, isJsonMode, outputJson, setJsonMode, setOutputPath, } from "./shared/json-output.js";
import { detectCI, setAutoConfirm, setNonInteractive } from "./shared/interactive.js";
import { redactForSerialization } from "../src/utils/index.js";
/**
 * Command registry mapping command names to their handlers.
 * Aliases (e.g. "preview" → serve, "g" → generate) are duplicate entries.
 */
const commands = {
    "init": async () => (await import("./commands/init/handler.js")).handleInitCommand,
    "dev": async () => (await import("./commands/dev/handler.js")).handleDevCommand,
    "build": async () => (await import("./commands/build/handler.js")).handleBuildCommand,
    "preview": async () => (await import("./commands/serve/handler.js")).handleServeCommand,
    "serve": async () => (await import("./commands/serve/handler.js")).handleServeCommand,
    "doctor": async () => (await import("./commands/doctor/handler.js")).handleDoctorCommand,
    "clean": async () => (await import("./commands/clean/handler.js")).handleCleanCommand,
    "analyze-chunks": async () => (await import("./commands/analyze-chunks/handler.js")).handleAnalyzeChunksCommand,
    "routes": async () => (await import("./commands/routes/handler.js")).handleRoutesCommand,
    "studio": async () => (await import("./commands/studio/handler.js")).handleStudioCommand,
    "styles": async () => (await import("./commands/styles/handler.js")).handleStylesCommand,
    "lock": async () => (await import("./commands/lock/handler.js")).handleLockCommand,
    "generate": async () => (await import("./commands/generate/handler.js")).handleGenerateCommand,
    "g": async () => (await import("./commands/generate/handler.js")).handleGenerateCommand,
    "pull": async () => (await import("./commands/pull/index.js")).handlePullCommand,
    "push": async () => (await import("./commands/push/index.js")).handlePushCommand,
    "project": async () => (await import("./commands/project/index.js")).handleProjectCommand,
    "projects": async () => (await import("./commands/project/index.js")).handleProjectCommand,
    "uploads": async () => (await import("./commands/uploads/index.js")).handleUploadsCommand,
    "files": async () => (await import("./commands/files/index.js")).handleFilesCommand,
    "knowledge": async () => (await import("./commands/knowledge/index.js")).handleKnowledgeCommand,
    "merge": async () => (await import("./commands/merge/handler.js")).handleMergeCommand,
    "deploy": async () => (await import("./commands/deploy/handler.js")).handleDeployCommand,
    "integration": async () => (await import("./commands/integration/handler.js")).handleIntegrationCommand,
    "env": async () => (await import("./commands/env/handler.js")).handleEnvCommand,
    "up": async () => (await import("./commands/up/index.js")).handleUpCommand,
    "schedule": async () => (await import("./commands/schedule/handler.js")).handleScheduleCommand,
    "schedules": async () => (await import("./commands/schedules/handler.js")).handleSchedulesCommand,
    "login": async () => async (args) => {
        const { hasProviderFlag, parseLoginMethod, reportRemovedProviderFlag } = await import("./auth/utils.js");
        const method = parseLoginMethod(args);
        // --json keeps its structured usage error, including for the removed
        // --provider flag: machine-readable output must never become prose.
        if (isJsonMode() && (hasProviderFlag(args) || method)) {
            await outputCliJsonError("login", {
                code: "USAGE_ERROR",
                slug: "invalid-arguments",
                registrySlug: "invalid-argument",
                message: "Explicit login methods are not supported with --json.",
            });
            exitProcess(2);
            return;
        }
        if (await reportRemovedProviderFlag("login", args)) {
            exitProcess(2);
            return;
        }
        const { login } = await import("./auth/index.js");
        if (!await login(method))
            exitProcess(1);
    },
    "logout": async () => async (args) => {
        const { reportRemovedProviderFlag } = await import("./auth/utils.js");
        if (await reportRemovedProviderFlag("logout", args)) {
            exitProcess(2);
            return;
        }
        const { logout } = await import("./auth/index.js");
        await logout();
    },
    "whoami": async () => async () => {
        const { whoami } = await import("./auth/index.js");
        // The exit code is the machine-readable answer: 0 authenticated, 1 not.
        if (!await whoami())
            exitProcess(1);
    },
    "install": async () => (await import("./commands/install/handler.js")).handleInstallCommand,
    "uninstall": async () => (await import("./commands/install/handler.js")).handleUninstallCommand,
    "demo": async () => (await import("./commands/demo/handler.js")).handleDemoCommand,
    "extension": async () => (await import("./commands/extension/handler.js")).handleExtensionCommand,
    "mcp": async () => (await import("./commands/mcp/handler.js")).handleMCPCommand,
    "issues": async () => (await import("./commands/issues/index.js")).handleIssuesCommand,
    "start": async () => (await import("./commands/start/handler.js")).handleStartCommand,
    "task": async () => (await import("./commands/task/handler.js")).handleTaskCommand,
    "eval": async () => (await import("./commands/eval/handler.js")).handleEvalCommand,
    "workflow": async () => (await import("./commands/workflow/handler.js")).handleWorkflowCommand,
    "worker": async () => (await import("./commands/worker/handler.js")).handleWorkerCommand,
    "schema": async () => (await import("./commands/schema/handler.js")).handleSchemaCommand,
    "test": async () => (await import("./commands/test/handler.js")).handleTestCommand,
    "lint": async () => (await import("./commands/lint/handler.js")).handleLintCommand,
    "skills": async () => (await import("./commands/skills/handler.js")).handleSkillsCommand,
    "config": async () => (await import("./commands/config/handler.js")).handleConfigCommand,
    "open": async () => (await import("./commands/open/handler.js")).handleOpenCommand,
    "docs": async () => async (args) => {
        const { runDocsCommand } = await import("./commands/docs/command.js");
        const { parsedDocsArguments } = await import("./commands/docs/arguments.js");
        exitProcess(await runDocsCommand(parsedDocsArguments(args)));
    },
    "completions": async () => (await import("./commands/completions/handler.js")).handleCompletionsCommand,
    "webhook": async () => (await import("./commands/webhook/handler.js")).handleWebhookCommand,
    "webhooks": async () => (await import("./commands/webhooks/handler.js")).handleWebhooksCommand,
};
/**
 * Show help for a specific command or main help
 */
function showHelp(command, showAll = false) {
    if (command) {
        showCommandHelp(command);
        return;
    }
    showMainHelp(showAll);
}
async function outputHelpJson(command, showAll) {
    if (command) {
        const help = getStructuredCommandHelp(command);
        if (!help) {
            await outputCliJsonError("help", {
                code: "USAGE_ERROR",
                slug: "invalid-arguments",
                registrySlug: "unknown-command",
                message: `Unknown command: ${command}`,
            });
            return false;
        }
        await outputJson(createSuccessEnvelope("help", { topic: command, help }));
        return true;
    }
    await outputJson(createSuccessEnvelope("help", getStructuredMainHelp(showAll)));
    return true;
}
function commandNameForJson(args) {
    const command = args._[0];
    return typeof command === "string" && command.length > 0 ? command : "cli";
}
const PROTECTED_DELETE_CONTEXT_LIMIT = 1_000;
function isRecord(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}
function boundedProtectedDeleteContext(context) {
    if (!isRecord(context) || !Array.isArray(context.protectedDeleted))
        return undefined;
    const protectedDeleted = context.protectedDeleted;
    const bounded = [];
    for (const path of protectedDeleted) {
        if (typeof path === "string")
            bounded.push(path);
        if (bounded.length === PROTECTED_DELETE_CONTEXT_LIMIT)
            break;
    }
    const redactedBounded = redactForSerialization(bounded);
    if (!Array.isArray(redactedBounded))
        return undefined;
    return {
        protectedDeleted: redactedBounded,
        ...(protectedDeleted.length > bounded.length
            ? {
                protectedDeletedTruncated: true,
                protectedDeletedOmitted: protectedDeleted.length - bounded.length,
            }
            : {}),
    };
}
function redactedProtectedDeleteContext(context) {
    const redacted = redactForSerialization(context);
    if (!isRecord(redacted))
        return undefined;
    const protectedDeleted = redacted.protectedDeleted;
    return Array.isArray(protectedDeleted) &&
        protectedDeleted.every((path) => typeof path === "string")
        ? { protectedDeleted }
        : undefined;
}
export function safeJsonErrorContext(context, originalError) {
    const integration = readIntegrationThrowableContext(originalError);
    if (integration)
        return integration;
    if (context === undefined)
        return undefined;
    if (isIntegrationErrorContext(context))
        return readIntegrationErrorContext(context);
    return boundedProtectedDeleteContext(context) ?? redactedProtectedDeleteContext(context);
}
async function outputCliJsonError(command, error) {
    await outputJson(createErrorEnvelope(command, error));
}
/** Classify a CLI failure from its registered exit-code contract. */
export function classifyCliError(error) {
    const usageError = error.exitCode === 2;
    return {
        code: usageError ? "USAGE_ERROR" : "RUNTIME_ERROR",
        slug: usageError ? "invalid-arguments" : "command-failed",
        exitCode: error.exitCode ?? 1,
    };
}
/**
 * Route and execute the appropriate CLI command
 *
 * @param args - Parsed CLI arguments
 */
export async function routeCommand(args) {
    // Handle global flags
    if (args["no-color"])
        setColorOverride(false);
    else if (args.color)
        setColorOverride(true);
    if (args.verbose)
        setVerboseMode(true);
    else if (args.quiet || args.q)
        setQuietMode(true);
    if (args.json || args.j)
        setJsonMode(true);
    if (typeof args.output === "string")
        setOutputPath(args.output);
    else if (typeof args.o === "string")
        setOutputPath(args.o);
    const autoConfirm = args.yes === true || args.y === true;
    setNonInteractive(args["no-input"] === true || autoConfirm || detectCI());
    setAutoConfirm(autoConfirm);
    if (args["no-animation"]) {
        const { setAnimationDisabled } = await import("./shared/animation.js");
        setAnimationDisabled(true);
    }
    // Start update check early so the network request runs during command execution
    const updateCheck = import("./shared/update-check.js")
        .then(({ checkForUpdates }) => checkForUpdates(VERSION))
        .catch(() => { });
    if (args.version || args.v) {
        if (isJsonMode()) {
            await outputJson(createSuccessEnvelope("version", {
                version: VERSION,
                deno: dntShim.Deno.version.deno,
                v8: dntShim.Deno.version.v8,
                typescript: dntShim.Deno.version.typescript,
                os: dntShim.Deno.build.os,
                arch: dntShim.Deno.build.arch,
                standalone: dntShim.Deno.build.standalone ?? false,
            }));
            exitProcess(0);
            return;
        }
        cliLogger.info(`Veryfront CLI v${VERSION}`);
        if (args.verbose) {
            cliLogger.info(`Deno ${dntShim.Deno.version.deno} (V8 ${dntShim.Deno.version.v8}, TypeScript ${dntShim.Deno.version.typescript})`);
            cliLogger.info(`OS: ${dntShim.Deno.build.os} ${dntShim.Deno.build.arch}`);
        }
        await updateCheck;
        exitProcess(0);
        return;
    }
    const command = args._[0];
    const secondCommand = args._[1];
    const duplicatedBinaryTarget = command === "veryfront" &&
        typeof secondCommand === "string" &&
        (secondCommand === "help" || Object.hasOwn(commands, secondCommand))
        ? secondCommand
        : undefined;
    if ((args.help || args.h) && !duplicatedBinaryTarget) {
        let helpTopic = command;
        if (command === "help") {
            helpTopic = typeof args._[1] === "string" ? args._[1] : undefined;
        }
        if (isJsonMode()) {
            const ok = await outputHelpJson(helpTopic, args.all === true);
            await updateCheck;
            exitProcess(ok ? 0 : 2);
            return;
        }
        showHelp(helpTopic, args.all === true);
        await updateCheck;
        exitProcess(0);
        return;
    }
    if (command === "help") {
        const topic = args._[1];
        const helpTopic = typeof topic === "string" ? topic : undefined;
        if (isJsonMode()) {
            const ok = await outputHelpJson(helpTopic, args.all === true);
            await updateCheck;
            exitProcess(ok ? 0 : 2);
            return;
        }
        showHelp(helpTopic, args.all === true);
        await updateCheck;
        exitProcess(0);
        return;
    }
    const loader = command ? commands[command] : undefined;
    if (command && !loader) {
        const { suggestCommand } = await import("./shared/suggest.js");
        const { COMMANDS } = await import("./help/command-definitions.js");
        // Use canonical command names from help registry (excludes aliases like "g", "preview")
        const canonicalNames = Object.keys(COMMANDS);
        const suggestions = duplicatedBinaryTarget
            ? [duplicatedBinaryTarget]
            : suggestCommand(command, canonicalNames);
        if (isJsonMode()) {
            await outputCliJsonError(command, {
                code: "USAGE_ERROR",
                slug: "unknown-command",
                message: `Unknown command: ${command}`,
                context: suggestions.length > 0 ? { suggestions } : {},
            });
            exitProcess(2);
            return;
        }
        cliLogger.error(`Unknown command: ${command}\n`);
        if (duplicatedBinaryTarget) {
            cliLogger.info('  You already included "veryfront". Remove the extra "veryfront" argument and run the command again.');
        }
        else if (suggestions.length > 0) {
            cliLogger.info(`  Did you mean?`);
            for (const s of suggestions) {
                const desc = COMMANDS[s]?.description ?? "";
                cliLogger.info(`    ${s}    ${desc}`);
            }
        }
        else {
            showHelp();
        }
        exitProcess(2);
        return;
    }
    await cliErrorBoundary(async () => {
        const handlerLoader = loader ?? commands.start;
        if (!handlerLoader)
            throw new Error("Start command is not registered");
        await ensureCliSchemaValidator();
        const handler = await handlerLoader();
        await handler(args);
    }, {
        onError: async (error, vfError) => {
            if (!isJsonMode()) {
                console.error((await import("../src/errors/index.js")).formatCLIError(vfError, {
                    color: shouldUseColor(),
                    verbose: isVerbose(),
                }));
                return;
            }
            const message = vfError.detail ?? vfError.message;
            const classification = classifyCliError(vfError);
            await outputCliJsonError(commandNameForJson(args), {
                code: classification.code,
                slug: classification.slug,
                registrySlug: vfError.slug,
                message: vfError.detail ?? message,
                context: safeJsonErrorContext(vfError.context, error),
            });
        },
        getExitCode: (_error, vfError) => classifyCliError(vfError).exitCode,
    });
    // Wait for update check to finish (with timeout to avoid hanging)
    await Promise.race([
        updateCheck,
        new Promise((r) => setTimeout(r, 5000)),
    ]);
}
